'use strict'

const EventEmitter = require('node:events')
const prettify = require('./pretty/prettify')
const SonicBoom = require('../sonic-boom')
const split = require('./pretty/split')
const { Duplex, pipeline } = require('node:stream')

function prettyTransport ({ colorize, customPrettifiers = {}, destination } = {}) {
  const enablePipelining = destination == null
  if (!(enablePipelining || destination instanceof SonicBoom || destination instanceof EventEmitter)) {
    destination = new SonicBoom(typeof destination === 'object' ? destination : { dest: destination })
  }
  colorize ??= (({ CI, FORCE_COLOR, NO_COLOR, NODE_ENV, TERM = 'term-color' }, { file, fd }) => {
    if (NO_COLOR != null || (file && FORCE_COLOR == null)) return false
    if (FORCE_COLOR != null || CI != null || NODE_ENV === 'test') return true
    if (!TERM.endsWith('color')) return false
    return fd === process.stdout.fd ? process.stdout.isTTY : fd === process.stderr.fd ? process.stderr.isTTY : false
  })(process.env, destination ?? {})
  const transform = prettify(customPrettifiers, colorize).on('error', (err) => {
    if (!enablePipelining) destination.release(err)
  })
  const source = split(parseLine).on('unknown', (line) => transform.push(line + '\n'))
  const done = pipelineDone.bind(null, source, transform)
  if (enablePipelining) return Duplex.from({ writable: source, readable: pipeline(source, transform, done) })
  return pipeline(source, transform, destination, done) && source
}

function pipelineDone (source, transform, err) {
  if (!err) return
  source.destroy(err)
  transform.destroy(err)
}

function parseLine (line) {
  try {
    const value = JSON.parse(line)
    if (value != null && value.constructor === Object) return value
    this.emit('unknown', line)
  } catch (err) {
    this.emit('unknown', line, err)
  }
}

module.exports = prettyTransport
